tasks.setup:
let score = 0;
let lives = 3;
let level = 1;
score = score + 10; // player scored
lives = lives - 1;  // player died
level = level + 1;  // next level
score = 0;          // reset score
console.log(`score=${score} lives=${lives} level=${level}`);

evidence.en:
// Part A is mid-calculation, expecting score to be non-zero:
let bonus = score * 2;   // reads score = 50 → bonus = 100 expected
// ...but Part B ran a reset first:
score = 0;               // reset the game
let bonus = score * 2;   // now reads score = 0 → bonus = 0

